, "control_products": {"type": "array", "items": {"type": "object", "required": ["name"], "properties": {"name": {"type": "string", "description": "原文有依据的产品名称。"}, "name_en": {"type": "string", "description": "原文有依据才输出。"}, "dosage_form": {"enum": ["片剂", "胶囊剂", "颗粒剂", "注射液", "冻干粉针剂", "口服溶液", "乳膏剂", "贴剂", "其他"], "type": "string", "description": "剂型；仅有明确依据时归一到候选值，一字不差；无法归一时省略，不猜测「其他」。"}, "specification_model": {"type": "string", "description": "原文有依据才输出。"}, "drug_registration_class": {"enum": ["化学药", "治疗用生物制品", "预防用生物制品", "中药", "天然药物"], "type": "string", "description": "药物注册分类；仅有明确依据时归一到候选值，一字不差；无法归一时省略，不猜测「其他」。"}}, "additionalProperties": false}, "description": "从研究用药/对照药表中逐行抽取对照产品；应急用药不属于对照产品。无依据时省略整个字段；行内只输出原文直接支持的 name、规格、剂型等子字段，不推断药物注册分类，不填空串。"}, "nmpa_document_no": {"type": "string", "description": "NMPA批件号或通知单号；保留原文编号，不与受理号混淆。"}, "planned_end_date": {"type": "string", "format": "date", "description": "计划结束日期；输出 YYYY-MM-DD。原文只有年-月时取该月最后一天，不得凭空补充具体日。"}, "primary_endpoint": {"type": "string", "description": "主要终点指标"}, "protocol_version": {"type": "string", "description": "方案版本号；将「第1.0版」「1.0版」等同义写法归一为「V1.0」格式；只保留原文直接给出的版本号，不补日期。"}, "registration_date": {"type": "string", "format": "date", "description": "登记日期；格式 YYYY-MM-DD。"}, "registration_type": {"enum": ["注册类", "非注册类"], "type": "string", "description": "注册类型；仅有明确依据时归一到候选值，一字不差；无法归一时省略，不猜测「其他」。"}, "exclusion_criteria": {"type": "string", "description": "排除标准；按原文编号逐条保留，不能合并、改写、跳项或只输出部分条目。"}, "inclusion_criteria": {"type": "string", "description": "入选标准；按原文编号逐条保留，不能合并、改写、跳项或只输出部分条目。"}, "nmpa_acceptance_no": {"type": "string", "description": "NMPA受理号；只有批件/通知书页直接给出时输出，不能用批件号代替。"}, "planned_start_date": {"type": "string", "format": "date", "description": "计划开始日期；输出 YYYY-MM-DD。原文只有年-月时取该月1日，不得凭空补充具体日。"}, "project_short_name": {"type": "string", "description": "项目简称。"}, "secondary_endpoint": {"type": "string", "description": "次要终点指标；按原文顺序完整提取所有条目，保留各项定义、时间点、适用范围和条件，包括括号及冒号后的内容。不得概括删减、合并或漏项，条目数量以原文为准。"}, "project_owner_email": {"type": "string", "description": "原文中的邮箱。"}, "project_owner_phone": {"type": "string", "description": "原文中的手机号，保留字符串。"}, "specification_model": {"type": "string", "description": "规格或型号。"}, "combination_products": {"type": "array", "items": {"type": "object", "required": ["name"], "properties": {"name": {"type": "string", "description": "原文有依据的产品名称。"}, "name_en": {"type": "string", "description": "原文有依据才输出。"}, "dosage_form": {"enum": ["片剂", "胶囊剂", "颗粒剂", "注射液", "冻干粉针剂", "口服溶液", "乳膏剂", "贴剂", "其他"], "type": "string", "description": "剂型；仅有明确依据时归一到候选值，一字不差；无法归一时省略，不猜测「其他」。"}, "specification_model": {"type": "string", "description": "原文有依据才输出。"}, "drug_registration_class": {"enum": ["化学药", "治疗用生物制品", "预防用生物制品", "中药", "天然药物"], "type": "string", "description": "药物注册分类；仅有明确依据时归一到候选值，一字不差；无法归一时省略，不猜测「其他」。"}}, "additionalProperties": false}, "description": "每行一个原文有依据的联合产品；应急用药不自动视为联合产品。 无依据时省略整个字段；行内无依据的可选子字段省略，不填空串。"}, "human_resource_review": {"type": "string", "description": "人类遗传资源采集/出境等备案情况描述。"}, "planned_subject_count": {"type": "number", "description": "总设计例数纯数字，不带单位。"}, "drug_registration_class": {"enum": ["化学药", "治疗用生物制品", "预防用生物制品", "中药", "天然药物"], "type": "string", "description": "药物注册分类；仅有明确依据时归一到候选值，一字不差；无法归一时省略，不猜测「其他」。"}}, "description": "只依据文档提取立项基本信息。可选字段无依据则省略，不输出 null 或空值占位。场景名称不是文档证据，不自动填入试验类型或注册类型。仅输出以字段键为属性的 JSON 对象，不输出 fields/value/confidence/source 包装。", "additionalProperties": false}, "extraction_strategy": "source_page_routed"}', NULL, NULL, '41c72e31-df43-440a-a0f3-b71f577bd29e', '2026-09-21 02:52:21.912677+00', '2026-09-28 03:45:29.223293+00');
